CREATE TABLE IF NOT EXISTS admins (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, created_at INTEGER NOT NULL, last_login INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS categories (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, sort INTEGER DEFAULT 0, enabled INTEGER DEFAULT 1, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS videos (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, subtitle TEXT DEFAULT '', year INTEGER DEFAULT 0, area TEXT DEFAULT '', language TEXT DEFAULT '', director TEXT DEFAULT '', actors TEXT DEFAULT '', tags TEXT DEFAULT '', poster TEXT DEFAULT '', backdrop TEXT DEFAULT '', description TEXT DEFAULT '', remarks TEXT DEFAULT '', category_id INTEGER, status INTEGER DEFAULT 1, featured INTEGER DEFAULT 0, hot INTEGER DEFAULT 0, hits INTEGER DEFAULT 0, score REAL DEFAULT 0, duration TEXT DEFAULT '', content TEXT DEFAULT '', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE IF NOT EXISTS sources (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, code TEXT UNIQUE NOT NULL, base_url TEXT DEFAULT '', enabled INTEGER DEFAULT 1, priority INTEGER DEFAULT 0, notes TEXT DEFAULT '', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS episodes (id INTEGER PRIMARY KEY AUTOINCREMENT, video_id INTEGER NOT NULL, source_id INTEGER NOT NULL, episode_no INTEGER DEFAULT 1, name TEXT DEFAULT '', url TEXT NOT NULL, enabled INTEGER DEFAULT 1, created_at INTEGER NOT NULL, FOREIGN KEY(video_id) REFERENCES videos(id) ON DELETE CASCADE, FOREIGN KEY(source_id) REFERENCES sources(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS logs (id INTEGER PRIMARY KEY AUTOINCREMENT, action TEXT, detail TEXT, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_videos_title ON videos(title);
CREATE INDEX IF NOT EXISTS idx_videos_updated ON videos(updated_at);
CREATE INDEX IF NOT EXISTS idx_videos_category ON videos(category_id);
CREATE INDEX IF NOT EXISTS idx_episodes_video ON episodes(video_id);
CREATE INDEX IF NOT EXISTS idx_episodes_source ON episodes(source_id);
